const dialog=document.querySelector('#booking');const form=document.querySelector('#booking-form');const result=document.querySelector('#result');document.querySelector('#year').textContent=new Date().getFullYear();document.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{form.hidden=false;result.hidden=true;document.querySelector('#format').value=button.dataset.format||'Помоги выбрать';dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);document.querySelector('#message').value=`Привет! Меня зовут ${data.get('name').trim()}. Хочу начать тренировки с MaxFit.\nЦель: ${data.get('goal')}.\nФормат: ${data.get('format')}.\nРасскажи, пожалуйста, об условиях и стоимости.`;form.hidden=true;result.hidden=false;document.querySelector('#copy-status').textContent='';document.querySelector('#copy').focus()});document.querySelector('#copy').addEventListener('click',async()=>{const message=document.querySelector('#message');try{await navigator.clipboard.writeText(message.value);document.querySelector('#copy-status').textContent='Скопировано. Заявка не отправлена.'}catch{message.focus();message.select();document.querySelector('#copy-status').textContent='Выделен текст заявки — скопируй его вручную.'}});
